// Model evaluation follows Netflix/vmaf's linear rescaling and libsvm RBF
// prediction at commit 4611e47a7330cd342498dcc130e1008efbeab6e4:
// libvmaf/src/predict.c:41-55,73-83,183-245,375-410 and
// libvmaf/src/svm.cpp:320-369,2505-2520. libsvm's original license is in
// licenses/LIBSVM-LICENSE. The support vectors are from the upstream float
// model and generated by tools/generate_vmaf_model.py.

#include "vmaf_model.h"

#include <algorithm>
#include <array>
#include <cmath>
#include <cstddef>
#include <stdexcept>

namespace vqm::internal {
namespace {

struct SupportVector {
    double coefficient;
    std::array<double, 6> values;
};

#include "vmaf_model_data.inc"

struct PredictorData {
    const double* slopes;
    const double* intercepts;
    const SupportVector* support_vectors;
    std::size_t support_vector_count;
    double gamma;
    double rho;
    const double* clip;
};

constexpr PredictorData kStandard1080{kSlopes1080.data(),
                                      kIntercepts1080.data(),
                                      kSupportVectors1080.data(),
                                      kSupportVectors1080.size(),
                                      kGamma1080,
                                      kRho1080,
                                      kClip1080.data()};
constexpr PredictorData kStandard4K{kSlopes4K.data(),
                                    kIntercepts4K.data(),
                                    kSupportVectors4K.data(),
                                    kSupportVectors4K.size(),
                                    kGamma4K,
                                    kRho4K,
                                    kClip4K.data()};

}  // namespace

double VmafV061Predict(
    const VmafV061Features& features, bool enable_transform, bool enable_clip,
    VmafModel model
) {
    const PredictorData* predictor = nullptr;
    if (model == VmafModel::Standard1080)
        predictor = &kStandard1080;
    else if (model == VmafModel::Standard4K)
        predictor = &kStandard4K;
    else
        throw std::invalid_argument("vmaf: unknown model");
    const std::array<double, 6> input = {features.adm2,   features.motion2,
                                         features.vif[0], features.vif[1],
                                         features.vif[2], features.vif[3]};
    std::array<double, 6> normalized{};
    for (std::size_t i = 0; i < input.size(); ++i) {
        if (!std::isfinite(input[i])) {
            throw std::invalid_argument("vmaf: model features must be finite");
        }
        normalized[i] =
            predictor->slopes[i + 1] * input[i] + predictor->intercepts[i + 1];
    }

    double sum = 0.0;
    for (std::size_t v = 0; v < predictor->support_vector_count; ++v) {
        const SupportVector& vector = predictor->support_vectors[v];
        double distance_squared = 0.0;
        for (std::size_t i = 0; i < normalized.size(); ++i) {
            const double difference = normalized[i] - vector.values[i];
            distance_squared += difference * difference;
        }
        sum +=
            vector.coefficient * std::exp(-predictor->gamma * distance_squared);
    }
    double score =
        (sum - predictor->rho - predictor->intercepts[0]) / predictor->slopes[0];
    if (enable_transform) {
        const double transformed = kTransform1080[0] +
                                   kTransform1080[1] * score +
                                   kTransform1080[2] * score * score;
        score = std::max(score, transformed);
    }
    return enable_clip
               ? std::clamp(score, predictor->clip[0], predictor->clip[1])
               : score;
}

}  // namespace vqm::internal
